package io.github.chronicle.core.roles;
import org.junit.jupiter.api.Test;
import java.io.IOException;
import java.util.*;
import java.nio.file.Files;
import java.nio.file.Path;
import static org.junit.jupiter.api.Assertions.*;
class PlayerRoleAssignmentServiceTest {
 static final class Memory implements PlayerRoleAssignmentRepository {PlayerRoleAssignments state=PlayerRoleAssignments.empty();boolean fail;public PlayerRoleAssignments load(){return state;}public void save(PlayerRoleAssignments s)throws IOException{if(fail)throw new IOException("disk");state=s;}}
 static PlayerRole role(String id,int cap){return new PlayerRole(id,id,"",true,cap,null,null,List.of(),List.of());}
 @Test void capacityIncludesOfflineSeatsAndReassignmentReleasesPriorSeat() throws Exception {Memory r=new Memory();var s=new PlayerRoleAssignmentService(r);UUID a=UUID.randomUUID(),b=UUID.randomUUID();Map<String,PlayerRole> roles=Map.of("test:one",role("test:one",1),"test:two",role("test:two",1));s.assign(a,"test:one",roles);assertThrows(IllegalStateException.class,()->s.assign(b,"test:one",roles));s.assign(a,"test:two",roles);s.assign(b,"test:one",roles);assertEquals("test:two",s.state().assigned().get(a));assertEquals("test:one",s.state().assigned().get(b));}
 @Test void failureDoesNotPublishAndMigrationIsOnceOnly() throws Exception {Memory r=new Memory();var s=new PlayerRoleAssignmentService(r);UUID a=UUID.randomUUID();r.fail=true;assertThrows(IOException.class,()->s.assign(a,"test:one",Map.of("test:one",role("test:one",1))));assertTrue(s.state().assigned().isEmpty());r.fail=false;s.bootstrapExisting(Set.of(a));long revision=s.state().revision();assertTrue(s.state().started().contains(a));s.bootstrapExisting(Set.of(UUID.randomUUID()));assertEquals(revision,s.state().revision());}
 @Test void explicitPolicyOffIsDurableAndDoesNotPublishOnFailure() throws Exception {Memory r=new Memory();var s=new PlayerRoleAssignmentService(r);UUID a=UUID.randomUUID();s.setPolicyDisabled(a,true,true);s.setPolicyDisabled(a,false,true);assertTrue(s.state().startingDisabled().contains(a));assertTrue(s.state().respawnDisabled().contains(a));r.fail=true;assertThrows(IOException.class,()->s.setPolicyDisabled(a,true,false));assertTrue(s.state().startingDisabled().contains(a));}
 @Test void strictStoreRejectsDuplicateAndFractionalState() throws Exception {Path file=Files.createTempFile("roles-state",".json");try{UUID id=UUID.randomUUID();Files.writeString(file,"{\"revision\":1.2,\"assigned\":[],\"started\":[],\"migratedExisting\":false}");assertThrows(IOException.class,()->new PlayerRoleAssignmentStore(file).load());Files.writeString(file,"{\"revision\":1,\"assigned\":[{\"player\":\""+id+"\",\"role\":\"test:one\"},{\"player\":\""+id+"\",\"role\":\"test:one\"}],\"started\":[],\"migratedExisting\":false}");assertThrows(IOException.class,()->new PlayerRoleAssignmentStore(file).load());Files.writeString(file,"{\"revision\":1,\"assigned\":[],\"started\":[],\"migratedExisting\":false}");var legacy=new PlayerRoleAssignmentStore(file).load();assertTrue(legacy.startingDisabled().isEmpty());assertTrue(legacy.respawnDisabled().isEmpty());}finally{Files.deleteIfExists(file);}}
}
